<?php
declare(strict_types=1);
require __DIR__.'/acceso.php'; require __DIR__.'/componentes/layout.php';
$stats=['opiniones'=>0,'usuarios'=>0,'precios'=>0,'acciones'=>0]; $recent=[]; $warnings=[];
try{$stats['opiniones']=(int)$pdo->query("SELECT COUNT(*) FROM testimonios WHERE estado='borrador'")->fetchColumn();}catch(Throwable $e){$failure=adminAuditFailure($pdo,'cargar_indicador_opiniones','inicio',null,$e);$warnings[]='Opiniones no disponibles. Referencia: '.$failure['reference'].'.';}
try{$stats['usuarios']=(int)$pdo->query('SELECT COUNT(*) FROM admin_usuarios WHERE activo=1')->fetchColumn();}catch(Throwable $e){$failure=adminAuditFailure($pdo,'cargar_indicador_usuarios','inicio',null,$e);$warnings[]='Usuarios no disponibles. Referencia: '.$failure['reference'].'.';}
try{require_once dirname(__DIR__).'/modulos/catalogo/Catalogo.php';$catalogo=new \RPV\Catalogo\Catalogo();$catalogData=$catalogo->leer();$stats['precios']=count(array_filter($catalogData['productos']??[],static fn($p)=>is_numeric($p['precio_clp']??null)&&($p['modo_precio']??'')!=='consultar'));}catch(Throwable $e){$failure=adminAuditFailure($pdo,'cargar_indicador_catalogo','inicio',null,$e);$warnings[]='Catalogo no disponible. Referencia: '.$failure['reference'].'.';}
try{$stats['acciones']=(int)$pdo->query('SELECT COUNT(*) FROM admin_log WHERE fecha>=DATE_SUB(NOW(),INTERVAL 7 DAY)')->fetchColumn();$recent=$pdo->query('SELECT fecha,evento,actor_usuario,entidad,entidad_id FROM admin_log ORDER BY id_log DESC LIMIT 8')->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){$failure=adminAuditFailure($pdo,'cargar_actividad_reciente','inicio',null,$e);$warnings[]='Auditoria no disponible. Referencia: '.$failure['reference'].'.';}
adminStart('Dashboard','dashboard','Estado real de la operacion administrativa');
foreach($warnings as $warning):?><div class="alert error"><?=h($warning)?></div><?php endforeach;?>
<section class="metric-grid" aria-label="Indicadores"><article class="card metric"><span>Opiniones pendientes</span><strong><?=number_format($stats['opiniones'],0,',','.')?></strong><a href="<?=h(url('/opiniones.php'))?>">Revisar</a></article><article class="card metric"><span>Usuarios activos</span><strong><?=number_format($stats['usuarios'],0,',','.')?></strong><a href="<?=h(url('/cuentas.php'))?>">Administrar</a></article><article class="card metric"><span>Productos con precio</span><strong><?=number_format($stats['precios'],0,',','.')?></strong><a href="<?=h(url('/precios.php'))?>">Ver catalogo</a></article><article class="card metric"><span>Acciones ultimos 7 dias</span><strong><?=number_format($stats['acciones'],0,',','.')?></strong><a href="<?=h(url('/auditoria-log.php'))?>">Consultar</a></article></section>
<div class="section-head"><div><h2>Modulos</h2><p>Accesos administrativos disponibles.</p></div></div><section class="module-grid"><?php foreach($modules->visible() as $id=>$module):if($id==='dashboard')continue;?><a class="card module-card" href="<?=h(url($module['ruta']))?>"><span class="icon" aria-hidden="true"><?=h(adminIcon($module['icono']))?></span><h3><?=h($module['nombre'])?></h3><p><?=h($module['descripcion'])?></p></a><?php endforeach;?></section>
<div class="section-head"><div><h2>Actividad reciente</h2><p>Ultimos eventos registrados, sin secretos ni credenciales.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Usuario</th><th>Evento</th><th>Entidad</th></tr></thead><tbody><?php if(!$recent):?><tr><td colspan="4" class="empty">No hay actividad registrada.</td></tr><?php endif;foreach($recent as $row):?><tr><td><?=h($row['fecha'])?></td><td><?=h($row['actor_usuario'])?></td><td><?=h(str_replace('_',' ',$row['evento']))?></td><td><?=h($row['entidad'])?><?=isset($row['entidad_id'])&&$row['entidad_id']!==null?' · '.h($row['entidad_id']):''?></td></tr><?php endforeach;?></tbody></table></div>
<?php adminEnd();
